function bindHoldButtons(){document.querySelectorAll('[data-hold]').forEach(btn=>{const key=btn.dataset.hold;const start=e=>{e.preventDefault();UAV.sim.holds[key]=true;btn.classList.add('active')};const stop=e=>{if(e)e.preventDefault();UAV.sim.holds[key]=false;btn.classList.remove('active')};btn.addEventListener('mousedown',start);btn.addEventListener('touchstart',start,{passive:false});window.addEventListener('mouseup',stop);window.addEventListener('touchend',stop)})}document.getElementById('armBtn').onclick=()=>UAV.sim.armed=true;document.getElementById('disarmBtn').onclick=()=>UAV.sim.armed=false;document.getElementById('stopBtn').onclick=()=>{UAV.sim.armed=false;UAV.sim.throttle=1000;document.getElementById('thrSlider').value=1000};bindHoldButtons();
